 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
                    nr, nc = rr+dr, cc+dc
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 5 and (nr,nc) not in seen:
                        seen.add((nr,nc)); stack.append((nr,nc))
            r0 = min(x for x,y in cells); r1 = max(x for x,y in cells)
            c0 = min(y for x,y in cells); c1 = max(y for x,y in cells)
            # Fill the hollow body of the three-sided frame.
            for rr in range(r0, r1+1):
                for cc in range(c0, c1+1):
                    if grid[rr][cc] == 0:
                        out[rr][cc] = 2
            # The break in the top edge projects a beam left along the row above it.
            top = [cc for rr,cc in cells if rr == r0]
            gaps = [cc for cc in range(c0, c1+1) if cc not in top]
            if r0 > 0 and gaps:
                gap = gaps[0]
                for cc in range(gap+1):
                    out[r0-1][cc] = 2
    return out
